type StrictHandlerFunc func(ctx *echo.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
}

// ListAudit operation middleware
func (sh *strictHandler) ListAudit(ctx *echo.Context, params ListAuditParams) error {
	var request ListAuditRequestObject

	request.Params = params

	handler := func(ctx *echo.Context, request interface{}) (interface{}, error) {
		return sh.ssi.ListAudit(ctx.Request().Context(), request.(ListAuditRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListAudit")
	}

	response, err := handler(ctx, request)

	if err != nil {
		return err
	} else if validResponse, ok := response.(ListAuditResponseObject); ok {
		return validResponse.VisitListAuditResponse(ctx.Response())
	} else if response != nil {
		return fmt.Errorf("unexpected response type: %T", response)
	}
	return nil
}

// ExportAudit operation middleware
func (sh *strictHandler) ExportAudit(ctx *echo.Context, params ExportAuditParams) error {
	var request ExportAuditRequestObject

	request.Params = params

	handler := func(ctx *echo.Context, request interface{}) (interface{}, error) {
		return sh.ssi.ExportAudit(ctx.Request().Context(), request.(ExportAuditRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ExportAudit")
	}

	response, err := handler(ctx, request)

	if err != nil {
		return err
	} else if validResponse, ok := response.(ExportAuditResponseObject); ok {
		return validResponse.VisitExportAuditResponse(ctx.Response())
	} else if response != nil {
		return fmt.Errorf("unexpected response type: %T", response)
	}
	return nil
}

// Login operation middleware
